package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import java.sql.Timestamp;
import java.time.Clock;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.node.ObjectNode;

class SourceDedupPartialSealTest {
    SourceDedupPartialArchiveTest a;SourceDedupPartialSealService service;JdbcSourceStageRoots roots;JdbcSourceDedupPartialReceipts receipts;
    SourceDedupPartialArchiveTest fixture(){return new SourceDedupPartialArchiveTest();}
    void setup(int count)throws Exception {a=fixture();a.setup(count,0);roots=new JdbcSourceStageRoots(a.f.f.db.source);receipts=new JdbcSourceDedupPartialReceipts(a.f.f.db.source);service=provider(a.f.f.db.writes);}
    SourceDedupPartialSealService provider(SharedWriteExecutor writes){return new SourceDedupPartialSealService(a.resolutions,a.service,receipts,roots,writes,new DataSourceTransactionManager(a.f.f.db.source),a.f.f.clock);}
    int seals(){return a.f.f.db.count("target_type='source_dedup_partial_result'");}
    @Test void actualSparseOriginalProofSealsOnceAndReadonlyRestartKeepsParentAndCallsUnchanged()throws Exception {
        setup(201);a.f.applied(0);a.f.terminal(1,"failed");a.f.applied(2);String parent=a.f.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,a.f.ref.ownerId());int calls=a.f.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);assertNull(a.f.f.read(()->service.readCommitted(a.f.ref)));var committed=service.seal(a.f.ref);assertNotNull(committed);assertEquals("source-dedup-stage-result-v2",CanonicalJson.parse(committed.proof().json()).get("schema_version").asText());assertEquals(6,CanonicalJson.parse(committed.receiptJson()).size());assertEquals(a.f.f.clock.instant(),committed.minimumObservationTime());assertEquals(1,seals());assertEquals(0,a.f.f.db.count("target_type='source_stage_availability'"));assertEquals(parent,a.f.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,a.f.ref.ownerId()));assertEquals(calls,a.f.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));int count=a.f.f.db.count("1=1");service=provider(a.f.f.db.writes);assertEquals(committed.receiptJson(),service.seal(a.f.ref).receiptJson());assertEquals(committed.proof().hash(),a.f.f.read(()->service.readCommitted(a.f.ref)).proof().hash());assertEquals(count,a.f.f.db.count("1=1"));assertEquals("CommittedSourceDedupPartial[redacted]",committed.toString());
    }
    @Test void actualWriterRollbackKeepsOnlyBlocksAndLostSealCommitAckRecovers()throws Exception {
        setup(1);a.f.terminal(0,"failed");a.f.f.db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_partial_seal_failure CHECK(target_type IS NULL OR target_type<>'source_dedup_partial_result')");assertThrows(RuntimeException.class,()->service.seal(a.f.ref));assertEquals(0,seals());assertEquals(2,a.blocks());assertNull(a.f.f.read(()->service.readCommitted(a.f.ref)));a.f.f.db.jdbc.execute(a.f.f.db.source instanceof org.h2.jdbcx.JdbcDataSource?"ALTER TABLE jobs DROP CONSTRAINT fictional_partial_seal_failure":"ALTER TABLE jobs DROP CHECK fictional_partial_seal_failure");
        var fault=new DataSourceTransactionManager(a.f.f.db.source){boolean lost;@Override protected void doCommit(org.springframework.transaction.support.DefaultTransactionStatus s){super.doCommit(s);if(!lost&&!TransactionSynchronizationManager.isCurrentTransactionReadOnly()){lost=true;throw new org.springframework.transaction.TransactionSystemException("fictional partial seal ACK lost");}}};var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(a.f.f.db.source),fault,()->25,n->{});var committed=provider(writes).seal(a.f.ref);assertEquals(committed.receiptJson(),service.seal(a.f.ref).receiptJson());assertEquals(1,seals());assertEquals(2,a.blocks());
    }
    @Test void nativeRevisionChangeImmediatelyBeforeWriterLocksRefusesAnySeal()throws Exception {
        setup(1);a.f.terminal(0,"failed");roots=spy(roots);doAnswer(call->{a.f.f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",a.f.plan.chunks().getFirst().rootId());return call.callRealMethod();}).when(roots).lockOriginal(anyList());service=provider(a.f.f.db.writes);assertThrows(RuntimeException.class,()->service.seal(a.f.ref));assertEquals(0,seals());assertEquals(2,a.blocks());roots=new JdbcSourceStageRoots(a.f.f.db.source);service=provider(a.f.f.db.writes);assertNotNull(service.seal(a.f.ref));assertEquals(1,seals());
    }
    @Test void changedNativeAfterSealDamagedArchiveAndRehashedClosedReceiptRemainRejected()throws Exception {
        setup(1);a.f.terminal(0,"failed");var committed=service.seal(a.f.ref);String owner=a.f.ref.ownerId(),id=JdbcSourceDedupPartialReceipts.receiptId(owner),root=a.f.plan.chunks().getFirst().rootId();var nativeRoot=a.f.f.read(()->roots.find(root));a.f.f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt().plusNanos(1000)),root);assertThrows(RuntimeException.class,()->a.f.f.read(()->service.readCommitted(a.f.ref)));a.f.f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt()),root);assertNotNull(a.f.f.read(()->service.readCommitted(a.f.ref)));
        for(String mode:java.util.List.of("extra","schema_version","result_hash","native_capture_hash","plan_ref","archive_ref","sealed_at")){
            var body=(ObjectNode)CanonicalJson.parse(committed.receiptJson());switch(mode){case "extra"->body.put("extra",true);case "plan_ref","archive_ref"->((ObjectNode)body.get(mode)).put("owner_job_id","fictional-other");case "sealed_at"->body.put(mode,"2020-01-01T00:00:00.000000Z");default->body.put(mode,"fictional-wrong");}String raw=JdbcFrozenInputs.canonical(body);a.f.f.db.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);assertThrows(RuntimeException.class,()->a.f.f.read(()->service.readCommitted(a.f.ref)),mode);a.f.f.db.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",committed.receiptJson(),JdbcGenerationLineage.hash(committed.receiptJson()),id);
        }
        a.f.f.db.jdbc.update("UPDATE jobs SET operator_id='fictional-other' WHERE id=?",id);assertThrows(RuntimeException.class,()->service.seal(a.f.ref));a.f.f.db.jdbc.update("UPDATE jobs SET operator_id=? WHERE id=?",JdbcSourceDedupPartialReceipts.ACTOR,id);a.f.f.db.jdbc.update("UPDATE jobs SET payload_hash=? WHERE purpose='result' AND owner_job_id=? AND part_no=1",new byte[32],owner);assertThrows(RuntimeException.class,()->a.f.f.read(()->service.readCommitted(a.f.ref)));assertEquals(1,seals());
    }
    @Test void pendingUnknownConfigurationCompleteZeroWrongTransactionsAndConstructorsDoNotGrantASeal()throws Exception {
        var data=mock(javax.sql.DataSource.class);new JdbcSourceDedupPartialReceipts(data);verifyNoInteractions(data);var resolution=mock(SourceStageResolutionService.class);var archive=mock(SourceDedupPartialArchiveService.class);var store=mock(JdbcSourceDedupPartialReceipts.class);var roots=mock(JdbcSourceStageRoots.class);var writes=mock(SharedWriteExecutor.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);new SourceDedupPartialSealService(resolution,archive,store,roots,writes,tx,Clock.systemUTC());verifyNoInteractions(resolution,archive,store,roots,writes,tx);
        setup(1);assertNull(service.seal(a.f.ref));for(String state:java.util.List.of("unknown_external","blocked_configuration")){a.f.f.db.jdbc.update("UPDATE jobs SET state=? WHERE id=?",state,a.f.plan.chunks().getFirst().rootId());assertNull(service.seal(a.f.ref));}assertEquals(0,seals());assertEquals(0,a.blocks());a.f.applied(0);assertNull(service.seal(a.f.ref));assertEquals(0,seals());assertThrows(RuntimeException.class,()->a.f.f.p1.tx(()->service.seal(a.f.ref)));assertThrows(RuntimeException.class,()->service.readCommitted(a.f.ref));assertThrows(RuntimeException.class,()->a.f.f.p1.tx(()->service.readCommitted(a.f.ref)));setup(0);assertNull(service.seal(a.f.ref));assertEquals(0,seals());assertEquals(0,a.blocks());
    }

    @Test void actualOriginalCaptureStorageCapacitySignalNeverWritesASeal(){
        assertDoesNotThrow(()->setup(1));a.f.terminal(0,"failed");roots=spy(roots);doThrow(new JdbcSourceStageRoots.CapacityRejected()).when(roots).lockOriginal(anyList());service=provider(a.f.f.db.writes);int calls=a.f.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);String parent=a.f.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,a.f.ref.ownerId());assertThrows(GenerationFlowService.CapacityGuarded.class,()->service.seal(a.f.ref));assertEquals(0,seals());assertEquals(2,a.blocks());assertEquals(calls,a.f.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(parent,a.f.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,a.f.ref.ownerId()));roots=new JdbcSourceStageRoots(a.f.f.db.source);service=provider(a.f.f.db.writes);assertNotNull(service.seal(a.f.ref));assertEquals(1,seals());
    }
}
